// MobEffectID returns the registry id for a mob_effect name.
func MobEffectID(name string) (int32, bool) {
	id, ok := mobEffectIDs[name]
	return id, ok
}

// MobEffectName returns the effect name for a registry id.
func MobEffectName(id int32) (string, bool) {
	for n, i := range mobEffectIDs {
		if i == id {
			return n, true
		}
	}
	return "", false
}

